# Exp11 · Kaggle baseline run — cross-hardware replication of exp10 geometry.
# GPU (T4, bf16) vs local (MPS, fp32): same recipes, same corpus bytes (our dataset),
# public container (Qwen2.5-0.5B-Instruct via HF). Scientific output = one JSON to /kaggle/working.
# Owner commission 2026-09-19: "以 qwen2.5 0.5b 做基线测试, 跑通整个流程".
import json, os, time, hashlib, itertools, base64
# image quirk 2026-09-19: kaggle base ships torchao 0.10 but peft demands >=0.16; we never use torchao — remove it
import subprocess as _sp, sys as _sys
_sp.run([_sys.executable, "-m", "pip", "uninstall", "-y", "torchao"], capture_output=True)
_EMBED_B64 = {"spring": {"sha256": "d38e57905b30a43ac624fd07b4a50b7704a6b712236635eefe6f3a8779394262", "b64": ""}, "summer": {"sha256": "e7246601f036edc21b81ba79a1654beca87892d3655d23b5c6d5b6484efb84f7", "b64": ""}, "mid": {"sha256": "7143b433fe7d61dc73c0bdfe7e48aa7699ff44273d4fa030260225f445f002ce", "b64": ""}}
import numpy as np
import torch
from transformers import AutoTokenizer, AutoModelForCausalLM
from peft import LoraConfig, get_peft_model, TaskType
from safetensors.torch import save_file

# Kaggle-models hub mount (official QwenLM mirror; byte-size identical to our manifest 88c14255…)
_MOUNT = "/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
MODEL_ID = _MOUNT if os.path.isdir(_MOUNT) else "Qwen/Qwen2.5-0.5B-Instruct"
import base64 as _b64
_EMBED = {"spring": {"sha256": "d38e57905b30a43ac624fd07b4a50b7704a6b712236635eefe6f3a8779394262"}, "summer": {"sha256": "e7246601f036edc21b81ba79a1654beca87892d3655d23b5c6d5b6484efb84f7"}, "mid": {"sha256": "7143b433fe7d61dc73c0bdfe7e48aa7699ff44273d4fa030260225f445f002ce"}}
_mount = "/kaggle/input/exp11-corpus"
if os.path.isdir(_mount):
    DATA = _mount
else:
    DATA = "/kaggle/working/corpus"; os.makedirs(DATA, exist_ok=True)
    for _n, _o in _EMBED_B64.items():
        _raw = _b64.b64decode(_o["b64"])
        assert hashlib.sha256(_raw).hexdigest() == _o["sha256"], "embedded corpus sha drift"
        open(os.path.join(DATA, f"corpus_{_n}.jsonl"), "wb").write(_raw)
OUT = "/kaggle/working"
RECIPE = dict(r=16, lora_alpha=32, lora_dropout=0.05,
              target_modules=["q_proj","k_proj","v_proj","o_proj","gate_proj","up_proj","down_proj"])
HP = dict(lr=1e-4, batch=2, accum=4, seed=13)
ARMS = {"spring": ("corpus_spring.jsonl", 6), "summer": ("corpus_summer.jsonl", 6), "mid": ("corpus_mid.jsonl", 3)}

def encode_pair(tok, user, assistant):
    msgs=[{"role":"user","content":user},{"role":"assistant","content":assistant}]
    prompt=tok.apply_chat_template(msgs[:1]+[{"role":"assistant","content":""}],tokenize=False,add_generation_prompt=True)
    full=tok.apply_chat_template(msgs,tokenize=False,add_generation_prompt=False)
    fi=tok(full,add_special_tokens=False)["input_ids"]; pi=tok(prompt,add_special_tokens=False)["input_ids"]
    return fi, [-100]*len(pi)+fi[len(pi):]

def collate(feats, tok):
    pad = tok.pad_token_id if tok.pad_token_id is not None else tok.eos_token_id
    L=max(len(f[0]) for f in feats)
    ids,lab,att=[],[],[]
    for i,l in feats:
        p=L-len(i); ids.append(i+[pad]*p); lab.append(l+[-100]*p); att.append([1]*len(i)+[0]*p)
    return torch.tensor(ids),torch.tensor(lab),torch.tensor(att)

t0=time.time()
dev="cuda" if torch.cuda.is_available() else "cpu"
tok=AutoTokenizer.from_pretrained(MODEL_ID)
tok.padding_side="right"
adapters={}; receipts={}
for arm,(fname,epochs) in ARMS.items():
    torch.manual_seed(HP["seed"])
    model=AutoModelForCausalLM.from_pretrained(MODEL_ID, dtype=torch.bfloat16)
    model=get_peft_model(model, LoraConfig(task_type=TaskType.CAUSAL_LM, **RECIPE, bias="none"))
    model.to(dev)
    feats=[]
    for line in open(os.path.join(DATA,fname)):
        m=json.loads(line)["messages"]
        feats.append(encode_pair(tok,m[0]["content"],m[1]["content"]))
    opt=torch.optim.AdamW([p for p in model.parameters() if p.requires_grad], lr=HP["lr"])
    last=0.0
    for ep in range(epochs):
        perm=torch.randperm(len(feats)); acc=nb=0
        for bi in range(0,len(feats),HP["batch"]):
            batch=[feats[i] for i in perm[bi:bi+HP["batch"]].tolist()]
            ids,lab,att=collate(batch,tok); ids,lab,att=ids.to(dev),lab.to(dev),att.to(dev)
            out=model(input_ids=ids,attention_mask=att,labels=lab)
            (out.loss/HP["accum"]).backward(); acc+=out.loss.item(); nb+=1
            if nb%HP["accum"]==0: opt.step(); opt.zero_grad()
        last=acc/nb
    sd={k:v.float().cpu() for k,v in model.state_dict().items() if "lora_" in k}
    fn=os.path.join(OUT,f"adapter_{arm}.safetensors"); save_file(sd,fn)
    adapters[arm]=sd
    receipts[arm]={"epochs":epochs,"final_loss":round(float(last),4),"file":os.path.basename(fn),
                   "sha256":hashlib.sha256(open(fn,'rb').read()).hexdigest()}
    del model; torch.cuda.empty_cache()
    print(arm,"done", receipts[arm]["final_loss"], flush=True)

# geometry: per-module k90 V-A sim + global dW overlap (exp10 metric set)
MODS=RECIPE["target_modules"]
import re as _re
def parse(ad):
    d={}
    for k,v in ad.items():
        mt=_re.search(r"layers\.([0-9]+)\..*?\.(q_proj|k_proj|v_proj|o_proj|gate_proj|up_proj|down_proj)\.lora_([AB])\.(?:default\.)?weight", k)
        if mt:
            d[(int(mt.group(1)), mt.group(2), mt.group(3))]=np.asarray(v,dtype=np.float64)
    assert len(d) >= 24, f"adapter keys unrecognised ({len(d)} matched) — check peft state-dict layout"
    return d
S={a:{k:np.linalg.svd(M,full_matrices=False) for k,M in parse(ad).items()} for a,ad in adapters.items()}
layers=sorted({k[0] for k in S["spring"]}); keys=list(itertools.product(layers,MODS))
def k90(s):
    e=s**2/(s**2).sum(); return int(np.searchsorted(np.cumsum(e),0.90)+1)
def dw(a):
    parts=[]
    for L,m in keys:
        Ua,sa,Vta=S[a][(L,m,"A")]; Wb,sb,Xtb=S[a][(L,m,"B")]
        A_mat=(Ua*sa)@Vta; B_mat=(Wb*sb)@Xtb
        parts.append((B_mat@A_mat).ravel())
    return np.concatenate(parts)
geo={}
for a1,a2 in itertools.combinations(ARMS,2):
    va=0.0
    for L,m in keys:
        _,s1,V1=S[a1][(L,m,"A")]; _,_,V2=S[a2][(L,m,"A")]
        k=k90(s1); va+=float(np.linalg.norm(V1[:k]@V2[:k].T,"fro"))
    d1,d2=dw(a1),dw(a2)
    geo[f"{a1}~{a2}"]={"V-A_k90":round(va/len(keys),3),
        "dWov":round(float(d1@d2/(np.linalg.norm(d1)*np.linalg.norm(d2))),4)}
_st = os.path.join(MODEL_ID, "model.safetensors")
_model_sha = hashlib.sha256(open(_st,"rb").read()).hexdigest() if os.path.exists(_st) else "n/a (internet fallback)"
report={"run":"exp11-kaggle-baseline","model_sha256":_model_sha,
 "model_source":"kaggle-models-hub-offline" if MODEL_ID==_MOUNT else "hf-download",
 "ts":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "hardware":{"gpu":torch.cuda.get_device_name(0) if dev=="cuda" else "cpu","backend":dev,"torch":torch.__version__},
 "model":MODEL_ID,"corpus_sha256":{k:_EMBED_B64[k]["sha256"] for k in _EMBED_B64},"minutes":round((time.time()-t0)/60,1),"hp":{**HP,"recipe":RECIPE},
 "receipts":receipts,"geometry":geo,
 "local_reference_exp10_s13":{"spring~summer":{"V-A":3.818,"dWov":-0.0022},"spring~mid":{"V-A":3.834,"dWov":0.0093},"summer~mid":{"V-A":3.833,"dWov":0.0128}},
 "attestation":"cross-hardware replication: bf16/CUDA vs fp32/MPS — sign & band stability are the test, not bit-equality"}
json.dump(report, open(os.path.join(OUT,"report_kaggle_baseline.json"),"w"), indent=1)
print(json.dumps(report["geometry"],indent=1))
